const sprintData = $('Obtener Sprint Activo').first().json.values[0];
const issues = ($input.first().json.issues) || [];
const sprintNumber = (sprintData.name.match(/\d+/) || [''])[0];

const formatDate = (iso) => {
  if (!iso) return '-';
  const d = new Date(iso);
  return `${String(d.getDate()).padStart(2, '0')}-${String(d.getMonth() + 1).padStart(2, '0')}-${d.getFullYear()}`;
};

const fechaInicio = formatDate(sprintData.startDate);
const fechaFin = formatDate(sprintData.endDate);

const CATEGORIES = [
  { key: 'POR HACER', color: '#64748B', bg: '#F1F5F9' },
  { key: 'EN CURSO', color: '#2563EB', bg: '#EFF6FF' },
  { key: 'CODE REVIEW', color: '#7C3AED', bg: '#F5F3FF' },
  { key: 'LISTO PARA QA', color: '#0EA5E9', bg: '#F0F9FF' },
  { key: 'QA', color: '#F59E0B', bg: '#FFFBEB' },
  { key: 'CON IMPEDIMIENTO', color: '#DC2626', bg: '#FEF2F2' },
  { key: 'LISTO PARA DESPLIEGUE', color: '#4F46E5', bg: '#EEF2FF' },
  { key: 'LISTO', color: '#16A34A', bg: '#F0FDF4' }
];

const mapStatus = (jiraStatus) => {
  const s = (jiraStatus || '').toLowerCase();
  if (s.includes('impedimento') || s.includes('impedimiento')) return 'CON IMPEDIMIENTO';
  if (s.includes('finalizada') || s.includes('done')) return 'LISTO';
  if (s.includes('listo para despliegue') || s.includes('deploy')) return 'LISTO PARA DESPLIEGUE';
  if (s.includes('validaci') && s.includes('po')) return 'LISTO PARA DESPLIEGUE';
  if (s.includes('code review')) return 'CODE REVIEW';
  if (s.includes('listo para qa') || s.includes('ready for qa')) return 'LISTO PARA QA';
  if (s.includes('control de calidad') || s.includes('qa')) return 'QA';
  if (s.includes('en curso') || s.includes('progress')) return 'EN CURSO';
  if (s.includes('backlog') || s.includes('por hacer') || s.includes('por definir') || s.includes('to do')) return 'POR HACER';
  return 'POR HACER';
};

const priorityStyle = (p) => {
  const s = (p || '').toLowerCase();
  if (s.includes('muy alta') || s.includes('highest') || s.includes('critica') || s.includes('crítica') || s.includes('urgente')) return { color: '#DC2626', bg: '#FEF2F2' };
  if (s.includes('alta') || s.includes('high')) return { color: '#F59E0B', bg: '#FFFBEB' };
  if (s.includes('muy baja') || s.includes('lowest')) return { color: '#16A34A', bg: '#F0FDF4' };
  if (s.includes('baja') || s.includes('low')) return { color: '#64748B', bg: '#F1F5F9' };
  return { color: '#2563EB', bg: '#EFF6FF' };
};

const counts = {};
CATEGORIES.forEach((c) => { counts[c.key] = 0; });

const rows = issues.map((issue) => {
  const statusName = issue.fields.status.name;
  const category = mapStatus(statusName);
  counts[category] = (counts[category] || 0) + 1;
  const cat = CATEGORIES.find((c) => c.key === category);
  const priorityName = issue.fields.priority ? issue.fields.priority.name : '-';
  const pStyle = priorityStyle(priorityName);
  return {
    key: issue.key,
    tipo: issue.fields.issuetype ? issue.fields.issuetype.name : '-',
    titulo: issue.fields.summary,
    estado: category,
    color: cat.color,
    bg: cat.bg,
    priority: priorityName,
    priorityColor: pStyle.color,
    priorityBg: pStyle.bg,
    asignado: issue.fields.assignee ? issue.fields.assignee.displayName : 'Sin asignar',
    alerta: (!issue.fields.assignee || category === 'CON IMPEDIMIENTO') ? '⚠️' : ''
  };
});

const getClosedSprints = (issue) => {
  if (issue.fields.closedSprints && Array.isArray(issue.fields.closedSprints)) return issue.fields.closedSprints;
  for (const [k, v] of Object.entries(issue.fields)) {
    if (k.startsWith('customfield_') && Array.isArray(v) && v.length > 0 && v[0] && v[0].state === 'closed' && v[0].name) return v;
  }
  return [];
};

const spilloverData = issues.map(issue => {
  const closed = getClosedSprints(issue);
  if (closed.length === 0) return null;
  const lastSprint = closed[closed.length - 1];
  const statusName = issue.fields.status.name;
  const cat = mapStatus(statusName);
  const catObj = CATEGORIES.find(c => c.key === cat);
  return {
    key: issue.key,
    titulo: issue.fields.summary,
    sprintOrigen: lastSprint.name || '-',
    estado: cat,
    color: catObj.color,
    bg: catObj.bg
  };
}).filter(Boolean);

const spilloverCount = spilloverData.length;

const escapedDefects = issues.filter(issue => {
  const labels = issue.fields.labels || [];
  return labels.some(l => l === 'Producción_PortalPacientes' || l === 'Produccion_PortalPacientes');
}).map(issue => {
  return { key: issue.key, titulo: issue.fields.summary, estado: issue.fields.status.name };
});
const escapedCount = escapedDefects.length;

const ticketsActivos = issues.length - counts['LISTO'];
const total = issues.length;
const pct = (n) => total > 0 ? Math.round((n / total) * 100) : 0;
const completado = counts['LISTO'];
const enProgreso = counts['EN CURSO'] + counts['CODE REVIEW'] + counts['QA'] + counts['LISTO PARA QA'] + counts['LISTO PARA DESPLIEGUE'];
const pendiente = counts['POR HACER'];
const conImpedimento = counts['CON IMPEDIMIENTO'];
const pctCompletado = pct(completado);
const pctEnProgreso = pct(enProgreso);
const pctPendiente = pct(pendiente);
const pctImpedimento = pct(conImpedimento);
const spilloverRate = total > 0 ? Math.round((spilloverCount / total) * 100) : 0;

const subject = `Portal Pacientes 📊 Certificación QA - Status Sprint ${sprintNumber} BUPA — ${fechaInicio} al ${fechaFin}`;

const cardHtml = (cat) => `<td width='25%' style='padding:4px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:${cat.bg}; border-left:4px solid ${cat.color}; border-radius:6px;'><tr><td style='padding:8px 10px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:16px; font-weight:700; color:${cat.color}; line-height:1;'>${counts[cat.key]}</div><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:9px; font-weight:700; letter-spacing:1px; color:#64748B; text-transform:uppercase; margin-top:3px;'>${cat.key}</div></td></tr></table></td>`;

const cardsRow1 = CATEGORIES.slice(0, 4).map(cardHtml).join('');
const cardsRow2 = CATEGORIES.slice(4, 8).map(cardHtml).join('');

const tableRows = rows.map((r) => `<tr><td width='90' style='padding:10px 16px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:600; color:#0747A6; white-space:nowrap; width:90px;'>${r.key}</td><td style='padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#475569;'>${r.tipo}</td><td style='padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B;'>${r.titulo}</td><td style='padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; white-space:nowrap;'><table role='presentation' cellpadding='0' cellspacing='0' border='0' style='display:inline-table;'><tr><td bgcolor='${r.priorityBg}' style='padding:4px 12px; border-radius:12px; font-size:11px; font-family:Segoe UI,Helvetica,Arial,sans-serif; white-space:nowrap;'><font color='${r.priorityColor}'><b>${r.priority}</b></font></td></tr></table></td><td style='padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; white-space:nowrap;'><table role='presentation' cellpadding='0' cellspacing='0' border='0' style='display:inline-table;'><tr><td bgcolor='${r.bg}' style='padding:4px 12px; border-radius:12px; font-size:11px; font-family:Segoe UI,Helvetica,Arial,sans-serif; white-space:nowrap;'><font color='${r.color}'><b>${r.estado}</b></font></td></tr></table></td><td style='padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#475569; white-space:nowrap;'>${r.asignado}</td><td style='padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:18px; text-align:center; white-space:nowrap;'>${r.alerta}</td></tr>`).join('');

const progressHtml = `<div style='padding:0 20px 24px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#FFFFFF; border-radius:6px; box-shadow:0 1px 3px rgba(15,23,42,0.08); border-top:3px solid #0747A6;'><tr><td style='padding:24px 24px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:14px; font-weight:700; letter-spacing:1px; text-transform:uppercase; color:#0747A6; margin-bottom:12px;'>📊 Progreso del Sprint</div><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#F1F5F9; border-radius:8px;'><tr><td style='background:#16A34A; border-radius:8px; height:24px; width:${pctCompletado}%; font-size:1px; line-height:24px;'>&nbsp;</td><td style='font-size:1px; line-height:24px;'>&nbsp;</td></tr></table><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:15px; color:#1E293B; margin-top:14px;'><strong style='color:#16A34A;'>${pctCompletado}% completado</strong> &middot; <strong style='color:#2563EB;'>${pctEnProgreso}% en progreso</strong> &middot; <strong style='color:#64748B;'>${pctPendiente}% pendiente</strong>${conImpedimento > 0 ? ` &middot; <strong style='color:#DC2626;'>${pctImpedimento}% con impedimento</strong>` : ''}</div></td></tr></table></div>`;

const spilloverRows = spilloverData.map(s => `<tr><td style='padding:8px 16px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:600; color:#0747A6; white-space:nowrap;'>${s.key}</td><td style='padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B;'>${s.titulo}</td><td style='padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#475569;'>${s.sprintOrigen}</td><td style='padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; white-space:nowrap;'><table role='presentation' cellpadding='0' cellspacing='0' border='0' style='display:inline-table;'><tr><td bgcolor='${s.bg}' style='padding:4px 12px; border-radius:12px; font-size:11px; font-family:Segoe UI,Helvetica,Arial,sans-serif; white-space:nowrap;'><font color='${s.color}'><b>${s.estado}</b></font></td></tr></table></td></tr>`).join('');

const spilloverHtml = spilloverCount > 0 ? `<div style='padding:0 20px 24px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#FFFFFF; border-radius:6px; box-shadow:0 1px 3px rgba(15,23,42,0.08); border-top:3px solid #F59E0B;'><tr><td style='padding:20px 24px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:14px; font-weight:700; letter-spacing:1px; text-transform:uppercase; color:#F59E0B; margin-bottom:4px;'>🔄 SPILLOVER</div><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:15px; color:#1E293B; margin-bottom:16px;'><strong>${spilloverCount}</strong> ticket${spilloverCount > 1 ? 's' : ''} arrastrado${spilloverCount > 1 ? 's' : ''} de sprints anteriores <span style='color:#64748B;'>(${spilloverRate}% del sprint)</span></div><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='border-collapse:collapse;'><thead><tr style='background:#FEF3C7;'><th align='left' style='padding:8px 16px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#92400E;'>Ticket</th><th align='left' style='padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#92400E;'>Título</th><th align='left' style='padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#92400E;'>Sprint Origen</th><th align='left' style='padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#92400E;'>Estado Actual</th></tr></thead><tbody>${spilloverRows}</tbody></table></td></tr></table></div>` : '';

const escapedRows = escapedDefects.map(e => `<tr><td style='padding:8px 16px; border-bottom:1px solid #FECACA; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:600; color:#0747A6; white-space:nowrap;'>${e.key}</td><td style='padding:8px 12px; border-bottom:1px solid #FECACA; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B;'>${e.titulo}</td><td style='padding:8px 12px; border-bottom:1px solid #FECACA; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#475569; white-space:nowrap;'>${e.estado}</td></tr>`).join('');

const escapedHtml = escapedCount > 0 ? `<div style='padding:0 20px 24px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#FFFFFF; border-radius:6px; box-shadow:0 1px 3px rgba(15,23,42,0.08); border-top:3px solid #DC2626;'><tr><td style='padding:20px 24px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0'><tr><td valign='top'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:14px; font-weight:700; letter-spacing:1px; text-transform:uppercase; color:#DC2626; margin-bottom:4px;'>🐛 ESCAPED DEFECTS — ENCONTRADOS EN PRODUCCIÓN</div><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#64748B; margin-bottom:16px;'>Bugs con etiqueta <strong style='color:#1E293B;'>Producción_PortalPacientes</strong> en el sprint activo</div></td><td valign='top' style='text-align:right; width:60px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:36px; font-weight:700; color:#DC2626; line-height:1;'>${escapedCount}</div></td></tr></table><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='border-collapse:collapse;'><thead><tr style='background:#FEE2E2;'><th align='left' style='padding:8px 16px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#991B1B;'>Ticket</th><th align='left' style='padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#991B1B;'>Título</th><th align='left' style='padding:8px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#991B1B;'>Estado</th></tr></thead><tbody>${escapedRows}</tbody></table></td></tr></table></div>` : '';

const body = `<div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; max-width:760px; margin:0 auto; background:#F4F6FB;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background-color:#0747A6;'><tr><td style='padding:28px 28px;' valign='top'><div style='color:#CFE2FF; font-size:11px; letter-spacing:3px; text-transform:uppercase; font-weight:700;'>Reporte Automático · Board PP</div><div style='color:#FFFFFF; font-size:22px; font-weight:700; margin-top:8px;'>📊 Sprint ${sprintNumber}${sprintData.goal ? ' — ' + sprintData.goal : ''}</div><div style='color:#CFE2FF; font-size:13px; margin-top:6px;'>Periodo: ${fechaInicio} al ${fechaFin}</div></td></tr></table>${progressHtml}<table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='padding:12px 20px;'><tr>${cardsRow1}</tr><tr>${cardsRow2}</tr></table>${escapedHtml}${spilloverHtml}<div style='padding:0 20px 24px; overflow-x:auto;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='border-collapse:collapse; background:#FFFFFF; border-radius:6px; overflow:hidden; box-shadow:0 1px 3px rgba(15,23,42,0.08);'><thead><tr style='background:#0747A6;'><th align='left' width='90' style='padding:10px 16px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF; white-space:nowrap; width:90px;'>Ticket</th><th align='left' style='padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;'>Tipo</th><th align='left' style='padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;'>Título</th><th align='left' style='padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;'>Prioridad</th><th align='left' style='padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;'>Estado Actual</th><th align='left' style='padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF; white-space:nowrap;'>Asignado a</th><th align='center' style='padding:10px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#FFFFFF;'>Alertas</th></tr></thead><tbody>${tableRows}</tbody></table></div><div style='padding:14px 20px; font-size:11px; color:#94A3B8; text-align:center; border-top:1px solid #E2E8F0;'>Generado automáticamente — WF-2.1 Status Sprint en Curso · ${new Date().toLocaleString('es-CL', { dateStyle: 'short', timeStyle: 'short' })}</div></div>`;

return [{ json: { subject, body } }];
